from decimal import Decimal


def _value(source: dict | None, key: str):
    if not source:
        return ""
    value = source.get(key, "")
    return "" if value is None else value


def _nvl(value, default):
    return default if value is None or value == "" else value


def _number(value) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _date_equal(value, literal: str) -> bool:
    return str(value) == literal


def _date_greater_equal(value, other: str) -> bool:
    value = str(value)
    other = str(other)
    if value == "00000000" or other == "00000000":
        return False
    return value >= other


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    stat_cd = _value(record, "STAT_CD")
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    amount = _number(_nvl(_value(record, "AMT"), 0))
    stage_pct = _number(_value(record, "STAGE_PCT"))

    def add(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    if event in ("INSERT", "UPDATE"):
        if not (amount >= 0):
            add("E3001", "Amount negative")

    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and amount == 0)):
            add("E3002", "Won opportunity requires amount")

    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "L" and lost_rsn == "")):
            add("E3003", "Lost reason required")

    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and _date_equal(close_dt, "00000000"))):
            add("E3004", "Won opportunity requires close date")

    if event == "UPDATE":
        old_stat_cd = _value(old, "STAT_CD")
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            add("E3005", "Cannot reopen a won opportunity")

    if event in ("INSERT", "UPDATE"):
        stage_consistent = (
            (stat_cd == "P" and stage_pct == 10)
            or (stat_cd == "Q" and stage_pct == 25)
            or (stat_cd == "N" and stage_pct == 60)
            or (stat_cd == "W" and stage_pct == 100)
            or (stat_cd == "L" and stage_pct == 0)
        )
        if not stage_consistent:
            add("E3006", "Stage percent inconsistent with status")

    if event == "INSERT":
        if not (
            _date_equal(close_dt, "00000000")
            or _date_greater_equal(close_dt, today)
        ):
            add("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
